CREATE TABLE public.institution_locations (id text PRIMARY KEY, province text NOT NULL, city text NOT NULL, name text NOT NULL, institution_type text NOT NULL CHECK(institution_type IN ('Public University','TVET College','Private Institution')), aliases text[] NOT NULL DEFAULT '{}', national boolean NOT NULL DEFAULT false, location_scope text NOT NULL DEFAULT 'city');
GRANT SELECT ON public.institution_locations TO anon,authenticated;
GRANT ALL ON public.institution_locations TO service_role;
ALTER TABLE public.institution_locations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "public institution directory" ON public.institution_locations FOR SELECT TO anon,authenticated USING(true);
CREATE INDEX institution_location_hierarchy ON public.institution_locations(province,city,institution_type);
ALTER TABLE public.listings ADD COLUMN institution_location_id text REFERENCES public.institution_locations(id);
CREATE OR REPLACE FUNCTION public.search_location_listings(_province text DEFAULT NULL,_city text DEFAULT NULL,_institution text DEFAULT NULL,_type text DEFAULT NULL,_query text DEFAULT NULL) RETURNS SETOF public.listings LANGUAGE sql STABLE SET search_path=public AS $$ SELECT l.* FROM public.listings l WHERE l.status='approved' AND (_province IS NULL OR l.province=_province) AND (_city IS NULL OR l.city=_city OR l.location ILIKE '%'||_city||'%') AND (_institution IS NULL OR l.institution=_institution OR EXISTS(SELECT 1 FROM public.institution_locations i WHERE (i.id=l.institution_location_id OR i.name=l.institution) AND (i.name=_institution OR _institution=ANY(i.aliases)))) AND (_type IS NULL OR EXISTS(SELECT 1 FROM public.institution_locations i WHERE (i.id=l.institution_location_id OR i.name=l.institution) AND i.institution_type=_type)) AND (_query IS NULL OR l.title ILIKE '%'||_query||'%' OR l.description ILIKE '%'||_query||'%' OR l.location ILIKE '%'||_query||'%' OR l.city ILIKE '%'||_query||'%' OR EXISTS(SELECT 1 FROM public.institution_locations i WHERE (i.id=l.institution_location_id OR i.name=l.institution OR l.institution=ANY(i.aliases)) AND (i.name ILIKE '%'||regexp_replace(_query,'^near\s+','','i')||'%' OR EXISTS(SELECT 1 FROM unnest(i.aliases) a WHERE a ILIKE '%'||regexp_replace(_query,'^near\s+','','i')||'%')))) ORDER BY l.created_at DESC $$;
REVOKE ALL ON FUNCTION public.search_location_listings(text,text,text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.search_location_listings(text,text,text,text,text) TO anon,authenticated;